import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import java.util.function.Function;
import java.util.function.Predicate;

public class Main {
    public static void main(String[] args) {
        List<String> words = new ArrayList<>(List.of("ant", "apple", "bear", "fig", "avocado", "kiwi", "cherry", "yak"));
        words.removeIf(w -> w.length() < 4);
        words.replaceAll(w -> w.toUpperCase());
        words.forEach(w -> System.out.println("word " + w));

        Predicate<String> startsWithA = w -> w.startsWith("A");
        Function<String, Integer> length = w -> w.length();
        Consumer<String> show = s -> System.out.println("* " + s);
        for (String w : words) {
            show.accept(w + " has " + length.apply(w) + " letters, starts with A: " + startsWithA.test(w));
        }

        int total = 0;
        for (String w : words) {
            total += length.apply(w);
        }
        System.out.println("Total letters: " + total);
    }
}

