import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

public class Main {
    public static void main(String[] args) {
        String[] votes = {"Cy", "Ana", "Ben", "Cy", "Dee", "Ana", "Ben", "Cy", "Ana"};
        String[][] cities = {{"Lyon", "France"}, {"Osaka", "Japan"}, {"Lima", "Peru"},
                {"Paris", "France"}, {"Kyoto", "Japan"}, {"Nice", "France"}};

        Map<String, Integer> tally = new TreeMap<>();
        Map<String, List<String>> byCountry = new TreeMap<>();
        for (String name : votes) {
            tally.merge(name, 1, Integer::sum);
        }
        for (String[] pair : cities) {
            byCountry.computeIfAbsent(pair[1], k -> new ArrayList<>()).add(pair[0]);
        }

        tally.forEach((name, count) -> System.out.println(name + ": " + count));
        byCountry.forEach((country, list) -> System.out.println(country + " -> " + list));

        List<Map.Entry<String, Integer>> entries = new ArrayList<>(tally.entrySet());
        Comparator<Map.Entry<String, Integer>> byVotes =
                Map.Entry.comparingByValue(Comparator.reverseOrder());
        entries.sort(byVotes.thenComparing(Map.Entry.comparingByKey()));
        for (int i = 0; i < 2; i++) {
            Map.Entry<String, Integer> e = entries.get(i);
            System.out.println((i + 1) + ". " + e.getKey() + " " + e.getValue());
        }
    }
}
